tape( 'the distribution prototype has a property for retrieving the distribution kurtosis', function test( t ) {
	var wald;

	t.strictEqual( hasOwnProp( Wald.prototype, 'kurtosis' ), true, 'has property' );

	wald = new Wald( 2.0, 4.0 );
	t.strictEqual( wald.kurtosis, kurtosis( 2.0, 4.0 ), 'returns expected value' );

	t.end();
});

